{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello रत्नेश जी आपको steam press boiler की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "चलिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "steam capacity की बात करें आपको किस steam capacity वाला चाहिए 500 kg प्रति घंटा या 300 kg प्रति घंटा या कुछ और?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "जो commercial use के लिए रहता है।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "समझ गई आप इसे अब बताइए commercial इस्तेमाल के लिए लेना चाह रहे हैं आपको I am interested in में used steam boilers या electric steam boiler चाहिए या कुछ और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "तीन।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब बताइए fuel type में क्या prefer करेंगे wood या electric या कुछ और?"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "अब बताइए।"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "electric."
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "electric fuel type के लिए prefer कर रहे हैं।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "अब आपको मैं seller details WhatsApp..."
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "तो मैं seller detail WhatsApp"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "business में है क्या?"
    }
  ]
}
